//! Human-readable Monotonic Timestamp Identifier (HMTID).
//!
//! An HMTID starts with a 14-digit UTC timestamp (`YYYYMMDDHHMMSS`) and ends with
//! 7 random Crockford Base32 characters, separated by `_` or `-`:
//!
//! ```text
//! 20260426035700_QZ998PX
//! 2026-04-26-03-57-00-QZ998PX   (time components separated too)
//! ```
//!
//! Within the same second the random part is incremented so that IDs generated by one
//! generator sort in creation order. This is a port of the `hmtid` npm package and keeps
//! its exact behaviour, including the forced timestamp advance when the random part
//! overflows.

use std::cmp::Ordering;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::str::FromStr;
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

use serde::{Deserialize, Serialize};

/// Crockford's Base32 alphabet (no I, L, O, U).
pub const ENCODING: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const RANDOM_LEN: usize = 7;
const TIME_DIGITS: usize = 14;
const TIME_MAX_MS: u64 = (1u64 << 48) - 1;

/// Why a string is not an HMTID.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum HmtidError {
    #[error("HMTID has an invalid length: {0}")]
    InvalidLength(usize),
    #[error("HMTID has an invalid separator: {0:?}")]
    InvalidSeparator(char),
    #[error("HMTID has an invalid timestamp: {0}")]
    InvalidTimestamp(String),
    #[error("HMTID has an invalid random part: {0}")]
    InvalidRandom(String),
}

/// A validated HMTID. Keeps the string exactly as written; two IDs are compared by their
/// timestamp and random part, so the same ID written with or without time separators is equal.
#[derive(Clone, Serialize, Deserialize)]
#[serde(try_from = "String", into = "String")]
pub struct Hmtid {
    text: String,
}

impl Hmtid {
    /// Parses and validates an HMTID string.
    pub fn parse(s: &str) -> Result<Hmtid, HmtidError> {
        validate(s)?;
        Ok(Hmtid {
            text: s.to_string(),
        })
    }

    /// The ID as written.
    pub fn as_str(&self) -> &str {
        &self.text
    }

    /// The 14 timestamp digits followed by the 7 random characters, without separators.
    pub fn canonical(&self) -> String {
        canonical(&self.text)
    }

    /// The timestamp part as `YYYYMMDDHHMMSS`.
    pub fn timestamp_digits(&self) -> String {
        self.canonical()[..TIME_DIGITS].to_string()
    }

    /// The 7 random characters.
    pub fn random_part(&self) -> String {
        self.canonical()[TIME_DIGITS..].to_string()
    }
}

fn canonical(s: &str) -> String {
    s.chars().filter(|c| *c != '-' && *c != '_').collect()
}

fn validate(s: &str) -> Result<(), HmtidError> {
    let bytes = s.as_bytes();
    let (time_part, sep, random_part): (String, u8, &[u8]) = match bytes.len() {
        22 => {
            let sep = bytes[14];
            (
                std::str::from_utf8(&bytes[..14]).unwrap_or("").to_string(),
                sep,
                &bytes[15..],
            )
        }
        27 => {
            // YYYY-MM-DD-HH-MM-SS-RRRRRRR
            let sep = bytes[4];
            for pos in [4usize, 7, 10, 13, 16, 19] {
                if bytes[pos] != sep {
                    return Err(HmtidError::InvalidSeparator(bytes[pos] as char));
                }
            }
            let digits: String = s.chars().take(19).filter(|c| *c != sep as char).collect();
            (digits, sep, &bytes[20..])
        }
        n => return Err(HmtidError::InvalidLength(n)),
    };
    if sep != b'-' && sep != b'_' {
        return Err(HmtidError::InvalidSeparator(sep as char));
    }
    if time_part.len() != TIME_DIGITS || !time_part.bytes().all(|b| b.is_ascii_digit()) {
        return Err(HmtidError::InvalidTimestamp(time_part));
    }
    if !is_valid_date_time(&time_part) {
        return Err(HmtidError::InvalidTimestamp(time_part));
    }
    if random_part.len() != RANDOM_LEN || !random_part.iter().all(|b| ENCODING.contains(b)) {
        return Err(HmtidError::InvalidRandom(
            String::from_utf8_lossy(random_part).into_owned(),
        ));
    }
    Ok(())
}

/// Checks `YYYYMMDDHHMMSS` for a real calendar date and time of day, like the Java `HMTID.of`.
fn is_valid_date_time(digits: &str) -> bool {
    let n = |a: usize, b: usize| digits[a..b].parse::<u32>().unwrap_or(99);
    let (y, m, d, hh, mm, ss) = (n(0, 4), n(4, 6), n(6, 8), n(8, 10), n(10, 12), n(12, 14));
    if !(1..=12).contains(&m) || hh > 23 || mm > 59 || ss > 59 || d == 0 {
        return false;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let days = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        _ => {
            if leap {
                29
            } else {
                28
            }
        }
    };
    d <= days
}

impl fmt::Display for Hmtid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

impl fmt::Debug for Hmtid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Hmtid({})", self.text)
    }
}

impl PartialEq for Hmtid {
    fn eq(&self, other: &Self) -> bool {
        self.canonical() == other.canonical()
    }
}

impl Eq for Hmtid {}

impl Hash for Hmtid {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.canonical().hash(state);
    }
}

impl PartialOrd for Hmtid {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Hmtid {
    fn cmp(&self, other: &Self) -> Ordering {
        self.canonical().cmp(&other.canonical())
    }
}

impl FromStr for Hmtid {
    type Err = HmtidError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Hmtid::parse(s)
    }
}

impl TryFrom<String> for Hmtid {
    type Error = HmtidError;

    fn try_from(value: String) -> Result<Self, Self::Error> {
        Hmtid::parse(&value)
    }
}

impl From<Hmtid> for String {
    fn from(value: Hmtid) -> Self {
        value.text
    }
}

impl AsRef<str> for Hmtid {
    fn as_ref(&self) -> &str {
        &self.text
    }
}

// ---------------------------------------------------------------------------
// Generation
// ---------------------------------------------------------------------------

/// Encodes a Unix timestamp in milliseconds as `YYYYMMDDHHMMSS`, optionally separated.
pub fn encode_time(now_ms: u64, separator: char, separate_time: bool) -> String {
    let now_ms = now_ms.min(TIME_MAX_MS);
    let secs = now_ms / 1000;
    let days = (secs / 86_400) as i64;
    let rem = secs % 86_400;
    let (y, m, d) = civil_from_days(days);
    let (hh, mm, ss) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    if separate_time {
        format!(
            "{y:04}{separator}{m:02}{separator}{d:02}{separator}{hh:02}{separator}{mm:02}{separator}{ss:02}"
        )
    } else {
        format!("{y:04}{m:02}{d:02}{hh:02}{mm:02}{ss:02}")
    }
}

/// Howard Hinnant's algorithm: days since 1970-01-01 to a proleptic Gregorian date.
fn civil_from_days(z: i64) -> (i64, u64, u64) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

/// Increments a Crockford Base32 string by one in its last position, carrying over.
/// Returns `None` when every character is already at its maximum.
pub fn increment_base32(s: &str) -> Option<String> {
    let mut chars: Vec<u8> = s.bytes().collect();
    let mut i = chars.len();
    while i > 0 {
        i -= 1;
        let pos = ENCODING.iter().position(|c| *c == chars[i])?;
        if pos == ENCODING.len() - 1 {
            chars[i] = ENCODING[0];
            continue;
        }
        chars[i] = ENCODING[pos + 1];
        return String::from_utf8(chars).ok();
    }
    None
}

fn max_random() -> String {
    std::iter::repeat_n(ENCODING[31] as char, RANDOM_LEN).collect()
}

fn min_random() -> String {
    std::iter::repeat_n(ENCODING[0] as char, RANDOM_LEN).collect()
}

fn random_chars() -> String {
    use rand::Rng;
    let mut rng = rand::rng();
    (0..RANDOM_LEN)
        .map(|_| ENCODING[rng.random_range(0..ENCODING.len())] as char)
        .collect()
}

#[derive(Debug, Default)]
struct State {
    last_time: u64,
    last_random: Option<String>,
    overflowed_time: u64,
}

/// A monotonic HMTID generator. Safe to share between threads.
#[derive(Debug)]
pub struct Generator {
    separator: char,
    separate_time: bool,
    state: Mutex<State>,
}

impl Generator {
    /// Creates a generator. `separator` is `'_'` or `'-'`; `separate_time` also puts the
    /// separator between the time components.
    pub fn new(separator: char, separate_time: bool) -> Generator {
        Generator {
            separator,
            separate_time,
            state: Mutex::new(State::default()),
        }
    }

    /// Generates the next ID for the current time.
    pub fn generate(&self) -> Hmtid {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_millis() as u64)
            .unwrap_or(0);
        self.generate_at(now)
    }

    /// Generates the next ID for the given Unix time in milliseconds.
    pub fn generate_at(&self, seed_time_ms: u64) -> Hmtid {
        let mut st = self.state.lock().unwrap_or_else(|e| e.into_inner());
        let mut seed = seed_time_ms;
        if seed < st.overflowed_time {
            seed = st.overflowed_time;
        }
        let text = if seed / 1000 <= st.last_time / 1000 {
            if st.last_random.as_deref() == Some(max_random().as_str()) {
                // The random part cannot grow any more: move the clock one second ahead
                st.last_time = (seed / 1000 + 1) * 1000;
                st.overflowed_time = st.last_time;
                st.last_random = Some(min_random());
                format!(
                    "{}{}{}",
                    encode_time(st.last_time, self.separator, self.separate_time),
                    self.separator,
                    min_random()
                )
            } else {
                let next = increment_base32(st.last_random.as_deref().unwrap_or(""))
                    .unwrap_or_else(min_random);
                st.last_random = Some(next.clone());
                format!(
                    "{}{}{}",
                    encode_time(st.last_time, self.separator, self.separate_time),
                    self.separator,
                    next
                )
            }
        } else {
            st.last_time = seed;
            let random = random_chars();
            st.last_random = Some(random.clone());
            format!(
                "{}{}{}",
                encode_time(seed, self.separator, self.separate_time),
                self.separator,
                random
            )
        };
        Hmtid { text }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn encodes_time_like_the_npm_package() {
        assert_eq!(encode_time(1_469_918_176_385, '_', false), "20160730223616");
        assert_eq!(
            encode_time(1_634_115_600_000, '-', true),
            "2021-10-13-09-00-00"
        );
    }

    #[test]
    fn parses_both_layouts() {
        let a = Hmtid::parse("20260426035700_QZ998PX").unwrap();
        let b = Hmtid::parse("2026-04-26-03-57-00-QZ998PX").unwrap();
        assert_eq!(a, b);
        assert_eq!(a.timestamp_digits(), "20260426035700");
        assert_eq!(a.random_part(), "QZ998PX");
        assert_eq!(b.to_string(), "2026-04-26-03-57-00-QZ998PX");
    }

    #[test]
    fn rejects_bad_input() {
        assert!(Hmtid::parse("").is_err());
        assert!(Hmtid::parse("2026-04-26-03-57-00-QZ998PI").is_err()); // I is not allowed
        assert!(Hmtid::parse("2026-04-26-03-57-00_QZ998PX").is_err()); // mixed separators
        assert!(Hmtid::parse("2026x04-26-03-57-00-QZ998PX").is_err());
        assert!(Hmtid::parse("not an id").is_err());
        assert!(Hmtid::parse("2026-13-29-00-00-01-AAAAAAA").is_err()); // month 13
        assert!(Hmtid::parse("2026-02-30-00-00-01-AAAAAAA").is_err()); // Feb 30
        assert!(Hmtid::parse("2026-09-29-24-00-01-AAAAAAA").is_err()); // hour 24
        assert!(Hmtid::parse("2024-02-29-23-59-59-AAAAAAA").is_ok()); // leap day
        assert!(Hmtid::parse("20260929000001-AAAAAAA").is_ok()); // compact with hyphen
    }

    #[test]
    fn orders_by_time_then_random() {
        let a = Hmtid::parse("2026-09-29-00-00-00-AAAAAAA").unwrap();
        let b = Hmtid::parse("2026-09-29-00-00-01-AAAAAAA").unwrap();
        let c = Hmtid::parse("2026-09-29-00-00-01-AAAAAAB").unwrap();
        assert!(a < b && b < c);
    }

    #[test]
    fn increments_within_the_same_second() {
        let g = Generator::new('-', true);
        let first = g.generate_at(1_634_115_600_000);
        let second = g.generate_at(1_634_115_600_500);
        assert_eq!(first.timestamp_digits(), second.timestamp_digits());
        assert_eq!(
            increment_base32(&first.random_part()).unwrap(),
            second.random_part()
        );
        assert!(first < second);
    }

    #[test]
    fn increment_carries() {
        assert_eq!(increment_base32("000000Z").unwrap(), "0000010");
        assert_eq!(increment_base32("ZZZZZZZ"), None);
    }

    #[test]
    fn advances_the_clock_on_overflow() {
        let g = Generator::new('_', false);
        {
            let mut st = g.state.lock().unwrap();
            st.last_time = 1_634_115_600_000;
            st.last_random = Some("ZZZZZZZ".to_string());
        }
        let id = g.generate_at(1_634_115_600_100);
        assert_eq!(id.as_str(), "20211013090001_0000000");
        let next = g.generate_at(1_634_115_600_200);
        assert_eq!(next.as_str(), "20211013090001_0000001");
    }
}
